"use client";

import { ConnectionSurface, connectionTarget } from "@diax/react/connect";
import type { DiaxRelation } from "diax";
import { BarChart3, Cloud, FileCode2, Globe2, Package, Smartphone, Syringe } from "lucide-react";

const distribution = { archive: "archive", engine: "engine", html: "html", cdn: "cdn" } as const;
const patch = {
  base: "step-base",
  track: "step-track",
  app: "step-app",
  baseLine: "line-base",
  metaLine: "line-meta",
  sdkLine: "line-sdk",
  appLine: "line-app",
} as const;

const distributionRelations = [
  edge("archive-engine", distribution.archive, distribution.engine, "#d58a3c"),
  edge("engine-html", distribution.engine, distribution.html, "#3ca2b8"),
  edge("engine-cdn", distribution.engine, distribution.cdn, "#3ca2b8"),
] as const satisfies readonly DiaxRelation<never>[];

const patchRelations = [
  edge("base-line", patch.base, patch.baseLine, "#d58a3c"),
  edge("track-meta", patch.track, patch.metaLine, "#3c9b71"),
  edge("track-sdk", patch.track, patch.sdkLine, "#3c9b71"),
  edge("app-line", patch.app, patch.appLine, "#ca5d88"),
] as const satisfies readonly DiaxRelation<never>[];

function edge(id: string, from: string, to: string, color: string): DiaxRelation<never> {
  return { id, from, to, color, targetMarker: "arrow", gap: 5 };
}

const node =
  "relative min-w-0 rounded-md border border-slate-700 bg-[#15212a] shadow-[0_10px_24px_rgb(0_0_0_/_0.2)]";

export default function HtmlInjectionMap() {
  return (
    <figure
      data-showcase-corpus="html-injection-map"
      className="w-full max-w-[1120px] overflow-hidden rounded-xl border border-slate-800 bg-[#080d12] p-3 text-slate-100 shadow-[0_24px_70px_rgb(0_0_0_/_0.28)] sm:p-6"
    >
      <figcaption className="mb-5 flex flex-col justify-between gap-3 border-b border-slate-800 pb-4 sm:flex-row sm:items-end">
        <div>
          <p className="m-0 font-mono text-[9px] font-bold uppercase tracking-[0.14em] text-[#d58a3c]">
            Two local connection surfaces
          </p>
          <h2 className="m-0 mt-1 text-xl font-semibold tracking-[-0.035em] sm:text-3xl">
            HTML injection map
          </h2>
          <p className="m-0 mt-1 text-[10px] leading-relaxed text-slate-400 sm:text-xs">
            Relations terminate on actual code lines without a port registry or imperative refresh.
          </p>
        </div>
        <dl className="m-0 flex gap-4 font-mono text-[8px] text-slate-400">
          <Stat label="Surfaces" value="2" />
          <Stat label="Targets" value="11" />
          <Stat label="Anchors" value="0" />
        </dl>
      </figcaption>

      <section
        className="mb-4 overflow-hidden rounded-lg border border-slate-800"
        aria-labelledby="distribution-title"
      >
        <ScopeHeading
          number="01"
          id="distribution-title"
          title="Artifact distribution"
          detail="Archive → injection engine → HTML and versioned assets"
        />
        <ConnectionSurface
          relations={distributionRelations}
          className="grid min-h-64 grid-cols-2 gap-x-10 gap-y-16 bg-[#0d141b] p-3 pb-14 [background-image:linear-gradient(rgb(60_162_184_/_0.04)_1px,transparent_1px),linear-gradient(90deg,rgb(60_162_184_/_0.04)_1px,transparent_1px)] [background-size:22px_22px] sm:grid-cols-[minmax(120px,.7fr)_minmax(120px,.7fr)_minmax(220px,1.6fr)] sm:grid-rows-2 sm:gap-x-16 sm:gap-y-3 sm:p-6 sm:pb-14"
        >
          <DistributionNode
            id={distribution.archive}
            icon={Package}
            eyebrow="Input"
            title="dist archive"
            detail="Unpack and classify"
            className="sm:row-span-2"
          />
          <DistributionNode
            id={distribution.engine}
            icon={Syringe}
            eyebrow="Transform"
            title="Inject & deploy"
            detail="base · tracking · app handoff"
            className="sm:row-span-2"
          />
          <DistributionNode
            id={distribution.html}
            icon={Globe2}
            eyebrow="HTML entry"
            title="Public route"
            detail="www.example.com/content/…"
          />
          <DistributionNode
            id={distribution.cdn}
            icon={Cloud}
            eyebrow="Static CDN"
            title="Versioned assets"
            detail="CSS · JS · images · fonts"
          />
        </ConnectionSurface>
      </section>

      <section
        className="overflow-hidden rounded-lg border border-slate-800"
        aria-labelledby="patch-title"
      >
        <ScopeHeading
          number="02"
          id="patch-title"
          title="Structured document patch"
          detail="Each transformation points to the real line it owns"
        />
        <ConnectionSurface
          relations={patchRelations}
          className="grid min-h-[500px] grid-cols-[minmax(86px,.7fr)_minmax(0,1.3fr)] gap-8 bg-[#0d141b] p-2.5 pb-14 sm:grid-cols-[minmax(210px,.72fr)_minmax(0,1.28fr)] sm:gap-16 sm:p-6 sm:pb-14"
        >
          <div className="grid grid-rows-3 gap-2 sm:gap-3">
            <Task
              id={patch.base}
              icon={Globe2}
              tone="orange"
              eyebrow="Path resolution"
              title="Inject <base href>"
              detail="Bundler stays publicPath-free."
            />
            <Task
              id={patch.track}
              icon={BarChart3}
              tone="green"
              eyebrow="Observability"
              title="Inject telemetry"
              detail="PV, UV and runtime errors."
            />
            <Task
              id={patch.app}
              icon={Smartphone}
              tone="pink"
              eyebrow="Mobile handoff"
              title="Inject app bridge"
              detail="Keep the content readable first."
            />
          </div>
          <section
            className="relative min-w-0 overflow-hidden rounded-lg border border-slate-700 bg-[#0a1016]"
            aria-labelledby="code-title"
          >
            <header className="flex items-center gap-2 border-b border-slate-800 bg-[#101820] px-2 py-2 text-slate-400 sm:px-3">
              <span className="flex gap-1" aria-hidden="true">
                <i className="size-1.5 rounded-full bg-red-400" />
                <i className="size-1.5 rounded-full bg-amber-400" />
                <i className="size-1.5 rounded-full bg-emerald-500" />
              </span>
              <h3
                id="code-title"
                className="m-0 min-w-0 flex-1 truncate font-mono text-[7px] font-semibold sm:text-[9px]"
              >
                index.html
              </h3>
              <FileCode2 aria-hidden="true" className="size-3" />
            </header>
            <div className="grid h-[calc(100%-30px)] grid-rows-3 gap-1 p-1.5 sm:gap-2 sm:p-3">
              <CodeGroup>
                <MutedCode>{"<html><head>"}</MutedCode>
                <InjectedCode id={patch.baseLine} tone="orange">
                  {'<base href="//cdn.example.com/{v}/">'}
                </InjectedCode>
              </CodeGroup>
              <CodeGroup>
                <InjectedCode id={patch.metaLine} tone="green">
                  {'<meta name="trace" content="content.read">'}
                </InjectedCode>
                <InjectedCode id={patch.sdkLine} tone="green">
                  {'<script src="//cdn.example.com/telemetry.js"></script>'}
                </InjectedCode>
              </CodeGroup>
              <CodeGroup>
                <MutedCode>{'<body><main id="app">…</main>'}</MutedCode>
                <InjectedCode id={patch.appLine} tone="pink">
                  {'<script src="//cdn.example.com/open-app.js"></script>'}
                </InjectedCode>
                <MutedCode>{"</body></html>"}</MutedCode>
              </CodeGroup>
            </div>
          </section>
        </ConnectionSurface>
      </section>
    </figure>
  );
}

function Stat({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt>{label}</dt>
      <dd className="m-0 mt-0.5 text-base font-semibold text-slate-100">{value}</dd>
    </div>
  );
}
function ScopeHeading({
  number,
  id,
  title,
  detail,
}: {
  number: string;
  id: string;
  title: string;
  detail: string;
}) {
  return (
    <header className="grid grid-cols-[auto_minmax(0,1fr)] items-center gap-2 border-b border-slate-800 bg-[#0c1319] p-2.5 sm:gap-3 sm:px-4">
      <span className="rounded border border-slate-600 px-1.5 py-1 font-mono text-[7px] font-bold tracking-wider text-[#d58a3c]">
        {number}
      </span>
      <div>
        <h2 id={id} className="m-0 text-[11px] font-semibold sm:text-sm">
          {title}
        </h2>
        <p className="m-0 mt-0.5 text-[7px] text-slate-400 sm:text-[9px]">{detail}</p>
      </div>
    </header>
  );
}
function DistributionNode({
  id,
  icon: Icon,
  eyebrow,
  title,
  detail,
  className = "",
}: {
  id: string;
  icon: typeof Package;
  eyebrow: string;
  title: string;
  detail: string;
  className?: string;
}) {
  return (
    <article
      {...connectionTarget(id)}
      className={`${node} flex items-center gap-2 p-2 sm:p-3 ${className}`}
    >
      <Icon aria-hidden="true" className="size-4 shrink-0 text-[#3ca2b8]" />
      <div className="min-w-0">
        <p className="m-0 font-mono text-[6px] font-bold uppercase tracking-wider text-[#d58a3c] sm:text-[7px]">
          {eyebrow}
        </p>
        <h3 className="m-0 mt-1 truncate text-[8px] font-semibold sm:text-[11px]">{title}</h3>
        <small className="mt-1 block truncate text-[6px] text-slate-400 sm:text-[8px]">
          {detail}
        </small>
      </div>
    </article>
  );
}
const taskTone = {
  orange: "border-orange-400/35 text-orange-300",
  green: "border-emerald-400/35 text-emerald-300",
  pink: "border-pink-400/35 text-pink-300",
} as const;
function Task({
  id,
  icon: Icon,
  tone,
  eyebrow,
  title,
  detail,
}: {
  id: string;
  icon: typeof Globe2;
  tone: keyof typeof taskTone;
  eyebrow: string;
  title: string;
  detail: string;
}) {
  return (
    <article {...connectionTarget(id)} className={`${node} ${taskTone[tone]} p-2 sm:p-3`}>
      <Icon aria-hidden="true" className="size-3.5" />
      <p className="m-0 mt-1.5 font-mono text-[5px] font-bold uppercase tracking-wider sm:text-[7px]">
        {eyebrow}
      </p>
      <h3 className="m-0 mt-1 text-[7px] font-semibold text-slate-100 sm:text-[11px]">{title}</h3>
      <small className="mt-1 block text-[5px] leading-snug text-slate-400 sm:text-[8px]">
        {detail}
      </small>
    </article>
  );
}
function CodeGroup({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex min-h-0 flex-col justify-center gap-1 border-b border-dashed border-slate-800 last:border-0 sm:gap-2">
      {children}
    </div>
  );
}
function MutedCode({ children }: { children: React.ReactNode }) {
  return (
    <code className="block break-all text-[5px] leading-snug text-slate-600 sm:text-[8px]">
      {children}
    </code>
  );
}
const codeTone = {
  orange: "border-orange-400/35 bg-orange-400/10 text-orange-300",
  green: "border-emerald-400/35 bg-emerald-400/10 text-emerald-300",
  pink: "border-pink-400/35 bg-pink-400/10 text-pink-300",
} as const;
function InjectedCode({
  id,
  tone,
  children,
}: {
  id: string;
  tone: keyof typeof codeTone;
  children: React.ReactNode;
}) {
  return (
    <code
      {...connectionTarget(id)}
      className={`relative block break-all rounded border border-l-2 p-1 text-[5px] leading-snug sm:p-2 sm:text-[8px] ${codeTone[tone]}`}
    >
      {children}
    </code>
  );
}
